const adjCard=()=>{const a=day().adj||[];return `<div class=card><div class="row sp"><h2 style="margin:0">Ajustes do dia</h2><button onclick=adjSheet()>± Ajustar</button></div>${a.map(x=>`<div class="row sp" style="margin-top:10px"><span>${x.v[0]>0?'+':''}${x.v[0]} kcal${x.v[1]||x.v[2]||x.v[3]?' · P'+x.v[1]+' C'+x.v[2]+' G'+x.v[3]:''}<br><small>${esc(x.n||'')}</small></span><button onclick="adjDel(${x.id})">✕</button></div>`).join('')||'<small>Tire ou some calorias e macros do dia sem mexer nos alimentos.</small>'}</div>`};
function adjSheet(){sheet(`<h2>Ajustar o dia (os alimentos não mudam)</h2><div class=row>${[['k','kcal'],['p','Prot'],['c','Carb'],['g','Gord']].map(a=>`<label style="flex:1;font-size:12px;color:var(--m)">${a[1]}<input id=aj${a[0]} type=number step=any value=0></label>`).join('')}</div><input id=ajn placeholder="Motivo (opcional)" style="margin:10px 0"><div class=row><button class=pri style="flex:1" onclick="adjOk(-1)">➖ Descontar</button><button style="flex:1" onclick="adjOk(1)">➕ Somar</button></div>`)}
const adjOk=s=>{const v=['k','p','c','g'].map(x=>s*Math.abs(+$('#aj'+x).value||0));if(v.some(n=>n)){const d=day();(d.adj=d.adj||[]).push({id:Date.now(),v,n:$('#ajn').value});save()}closeS();render()};
const adjDel=id=>{const d=day();d.adj=d.adj.filter(x=>x.id!=id);save();render()};
// ---- quanto cabe
function room(){const el=$('#rm');if(!el)return;if(F.meal==NC){el.textContent=tl('Não entra na conta do dia.');return}const d=day(),m=mx(F.meal),cur=d.food.find(x=>x.id==F.id),used=mk(d.food.filter(x=>x.id!=F.id&&x.meal==F.meal)),dl=gk(D)-tot(D)[0]+(cur?cur.v[0]:0),left=m?Math.min(m-used,dl):dl,k100=F.gr>0?F.v[0]/F.gr*100:0,g=k100>0?Math.max(0,Math.round(left/k100*100)):0;
el.innerHTML=(left<0?'Passa em <b>'+Math.round(-left)+' kcal</b>':'Sobra <b>'+Math.round(left)+' kcal</b>')+(m?' nesta refeição (máx. '+m+')':' no dia')+(k100>0?' → cabem <b>'+g+' g</b>'+(F.u>0?' (~'+Math.floor(g/F.u)+' un)':'')+' <button onclick="useRoom('+g+')" style="padding:4px 10px">usar</button>':'');trDom(el)}
const useRoom=g=>{const o=F.gr;F.gr=g;$('#fgr').value=g;fill(o);syncU()};
const byK=()=>{const kc=+$('#fkc').value,k100=F.gr>0?F.v[0]/F.gr*100:0;if(!kc||!k100)return toast('Escolha um alimento e digite as kcal');const o=F.gr;F.gr=+(kc/k100*100).toFixed(0);$('#fgr').value=F.gr;fill(o);syncU()};
