// ---- planos (PDF/imagens) e música
const PL=()=>S.plans||(S.plans=[]);
function vPlanos(){return `<h1>Planos de treino</h1><p style="color:var(--m)">Guarde PDFs e imagens dos seus treinos e abra quando quiser.</p><label class=pri style="display:block;text-align:center;padding:12px;border-radius:12px;margin:10px 0">+ Adicionar PDF ou imagem<input type=file accept="application/pdf,image/*" style="display:none" onchange="addPlan(this)"></label>`+PL().map(p=>`<div class="card row sp"><span onclick="openPlan(${p.id})" style="flex:1">${p.t=='pdf'?'📄':'🖼️'} ${esc(p.n)}</span><button onclick="renPlan(${p.id})">✏️</button><button onclick="delPlan(${p.id})">🗑</button></div>`).join('')}
function addPlan(el){const f=el.files[0];if(!f)return;const r=new FileReader();r.onload=async()=>{const id=Date.now();await ph('put','w'+id,r.result);PL().push({id,n:f.name.replace(/\.[^.]+$/,''),t:f.type=='application/pdf'?'pdf':'img'});save();render();toast('Salvo')};r.readAsDataURL(f)}
async function openPlan(id){const p=PL().find(x=>x.id==id),u=await ph('get','w'+id);if(!u)return toast('Arquivo não encontrado');if(p.t=='img')return sheet(`<img src="${u}" style="width:100%;border-radius:12px">`);try{const w=await C().Filesystem.writeFile({path:'plano'+id+'.pdf',data:u.split(',')[1],directory:'CACHE'});await C().FileOpener.open({filePath:w.uri,contentType:'application/pdf'})}catch(e){toast('Não consegui abrir o PDF')}}
const renPlan=id=>{const p=PL().find(x=>x.id==id),n=prompt('Nome:',p.n);if(n){p.n=clean(n)||p.n;save();render()}};
const delPlan=id=>{if(confirm('Apagar este arquivo?')){S.plans=PL().filter(x=>x.id!=id);ph('del','w'+id);save();render()}};
const embed=u=>{let m;if(m=u.match(/open\.spotify\.com\/(?:intl-[a-z]+\/)?(playlist|album|track|artist|show|episode)\/([A-Za-z0-9]+)/))return 'https://open.spotify.com/embed/'+m[1]+'/'+m[2];if(m=u.match(/[?&]list=([\w-]+)/))return 'https://www.youtube.com/embed/videoseries?list='+m[1];if(m=u.match(/(?:youtu\.be\/|[?&]v=)([\w-]{6,})/))return 'https://www.youtube.com/embed/'+m[1];return ''};
const plAdd=()=>{const u=prompt('Cole o link da playlist (Spotify ou YouTube):');if(!u)return;const n=clean(prompt('Nome da playlist:','Treino'))||'Playlist';(S.pl=S.pl||[]).push({n,u:u.trim()});save();PS=S.pl.length-1;render()};
const plDel=i=>{S.pl.splice(i,1);PS=-1;save();render()};
const plOpen=i=>{location.href=S.pl[i].u};
