// ---- calendário do celular
const CAL=()=>C().CapacitorCalendar;
async function calAdd(){const P=CAL();if(!P||!S.calOn)return toast('Sincronize primeiro');if(!confirm('Criar os horários de comer dos próximos 7 dias no seu calendário?'))return;try{const n=new Date();let c=0;for(let i=0;i<7;i++){const d0=new Date(n.getFullYear(),n.getMonth(),n.getDate()+i);if(!S.fast.days.includes(d0.getDay()))continue;for(const w of S.fast.w){const s=mm(w.s),e=mm(w.e);await P.createEvent({title:'🍽️ Janela de comer',startDate:d0.getTime()+s*6e4,endDate:d0.getTime()+(e<=s?e+1440:e)*6e4});c++}}toast(c+' eventos criados');calLoad()}catch(e){toast('Não consegui criar os eventos')}}
function dayCard(){const d=CD,t=tot(d),a=S.days[d]||{todo:{}},dn=S.tasks.filter(x=>a.todo[x.id]).length;return `<div class=card><h2>${lbl(d)}</h2><div class="row sp"><span>🍽️ ${Math.round(t[0])} / ${gk(d)} kcal</span><span>✅ ${dn}/${S.tasks.length}</span><span>📝 ${(a.jn||[]).length}</span></div>${a.why&&a.why.r.length?'<p style="margin-top:8px"><small>Motivo: '+a.why.r.join(', ')+'</small></p>':''}${(EV[d]||[]).map(e=>`<p style="margin-top:8px">📅 ${esc(e.title||'Evento')}<br><small>${new Date(e.startDate).toLocaleTimeString(LC(),{hour:'2-digit',minute:'2-digit'})}</small></p>`).join('')}<div class=row style="margin-top:12px"><button onclick="D='${d}';go('dieta')">Diário</button><button onclick="D='${d}';go('tarefas')">Tarefas</button></div></div>`}
