const bkJ=()=>{const o=Object.assign({},S);delete o.calOn;return JSON.stringify(o)};
function bkSheet(){sheet(`<h2>Backup</h2><p style="font-size:13px;margin-bottom:10px;color:var(--m)">Fotos e arquivos de treino não entram no backup.</p><div class=row style="flex-wrap:wrap"><button class=pri onclick=bkShare()>Compartilhar / salvar</button><button onclick=bkCopy()>Copiar</button></div><h2 style="margin-top:20px">Restaurar</h2><textarea id=bkt rows=4 placeholder="Cole o backup aqui"></textarea><label style="display:block;margin:8px 0;font-size:13px;color:var(--m)">ou escolha o arquivo<input type=file accept=".json,.txt,application/json,text/plain" onchange="bkFile(this)"></label><button class=pri style="width:100%" onclick=bkRestore()>Restaurar agora</button>`)}
async function bkShare(){try{await C().Share.share({title:'Backup Jejum e Dieta',text:bkJ(),dialogTitle:'Salvar backup'})}catch(e){toast('Use o botão Copiar')}}
function bkCopy(){try{const t=document.createElement('textarea');t.value=bkJ();document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();if(ok)return toast('Backup copiado')}catch(e){}navigator.clipboard?navigator.clipboard.writeText(bkJ()).then(()=>toast('Backup copiado'),()=>toast('Use Compartilhar')):toast('Use Compartilhar')}
const bkFile=el=>{const f=el.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{$('#bkt').value=r.result};r.readAsText(f)};
const bkRestore=()=>{try{const o=JSON.parse($('#bkt').value.trim());if(!o||!o.days)throw 0;S=Object.assign({},def,o);S.calOn=0;fixS();save();closeS();render();toast('Backup restaurado')}catch(e){toast('Backup inválido: cole o texto completo')}};
