s.forEach(w=>{const cy=(w.y0+w.y1)/2,r=A[A.length-1];if(r&&Math.abs(cy-r.cy)<mh*.55){r.w.push(w);r.cy=r.w.reduce((n,z)=>n+(z.y0+z.y1)/2,0)/r.w.length}else A.push({cy,w:[w]})});
