const MASS={g:1,mg:1e-3,'µg':1e-6},EXP={kcal:'kcal',prot:'g',carb:'g',fat:'g',sat:'g',trans:'g',sug:'g',fib:'g',na:'mg',ca:'mg',fe:'mg',k:'mg',chol:'mg',mg:'mg',zn:'mg',p:'mg',vC:'mg',vE:'mg',vA:'µg',vD:'µg',vK:'µg',vB12:'µg',fol:'µg'};
