async function npLoad(){const e=$('#np');if(!e)return;const P=C().MediaNow;if(!P){e.innerHTML='<small>Disponível só no app instalado</small>';trDom(e);return}try{const a=await P.enabled();if(!a.on){e.innerHTML='<p style="margin-bottom:10px"><small>Para ver o que está tocando, ative o acesso a notificações para este app.</small></p><button class=pri onclick="C().MediaNow.settings()">Ativar acesso às notificações</button>';trDom(e);return}const n=await P.now();if(!n.has){e.innerHTML='<small>Nada tocando</small>';trDom(e);return}const ft=ms=>fmtT(Math.floor((ms||0)/1000));
e.innerHTML=`<div class=row>${n.art?`<img src="data:image/jpeg;base64,${n.art}" style="width:84px;height:84px;border-radius:12px;object-fit:cover">`:''}<div style="flex:1;min-width:0"><div class=big style="font-size:19px">${esc(n.title||'—')}</div><small>${esc(n.artist||'')}${n.album?' · '+esc(n.album):''}</small><br><small>${esc(APPN[n.app]||n.app)}</small></div></div>${n.dur>0?`<div class=row style="margin-top:12px"><small>${ft(n.pos)}</small><input type=range min=0 max=${n.dur} value=${n.pos} style="margin:0;padding:0" onchange="npCmd('seek',{ms:+this.value})"><small>${ft(n.dur)}</small></div>`:''}<div class=row style="margin:12px 0"><button style="flex:1" onclick="npCmd('prev')">⏮</button><button class=pri style="flex:2" onclick="npCmd('pp')">${n.playing?'⏸':'▶'}</button><button style="flex:1" onclick="npCmd('next')">⏭</button></div>${n.queue&&n.queue.length?'<h2>Fila</h2>'+n.queue.map(q=>`<div class=row style="padding:8px 0;border-top:1px solid var(--ln);${q.id==n.active?'font-weight:600;color:var(--a)':''}" onclick="npCmd('queue',{id:${q.id}})"><span>${q.id==n.active?'▶':'•'}</span><span style="flex:1">${esc(q.t)}</span></div>`).join(''):'<small>Este player não compartilha a fila. Salve o link da playlist abaixo para vê-la aqui.</small>'}`;trDom(e)}catch(x){e.innerHTML='<small>'+esc(String(x.message||x))+'</small>'}}
